mapper.select:
SELECT NVL(SUM(ci.QUANTITY), 0)
FROM OFT_CART c
JOIN OFT_CART_ITEM ci
    ON ci.CART_NO = c.CART_NO
WHERE c.USER_NO = #{userNo}
  AND ci.PRODUCT_NO = #{productNo}

mapper.update:
UPDATE OFT_CART_GROUP
SET GROUP_NAME = #{groupName}
WHERE CART_GROUP_NO = #{cartGroupNo}

UPDATE OFT_CART_GROUP
SET UPDATED_AT = SYSTIMESTAMP
WHERE CART_GROUP_NO = #{_parameter}

UPDATE OFT_CART_ITEM
SET QUANTITY = #{quantity}
WHERE CART_ITEM_NO = #{cartItemNo}

mapper.delete:
DELETE FROM OFT_CART_GROUP
WHERE CART_GROUP_NO = #{_parameter}
  AND NOT EXISTS (
      SELECT 1
      FROM OFT_CART_ITEM
      WHERE CART_GROUP_NO = #{_parameter}
  )
